}];

const p = $json.body ?? $json;

function esc(v) {
  if (v === null || v === undefined || v === '') return '';
  return String(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function fmtDate(v) {
  if (!v) return '';
  try {
    return new Date(v).toLocaleString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  } catch {
    return String(v);
  }
}

const severityIcon = {
  CRITICAL: '🔴',
  MAJOR: '🟠',
  WARNING: '🟡',
  INFO: '🔵',
};

const eventIcon = {
  OPENED: '🚨',
  ESCALATED: '⬆️',
  RESOLVED: '✅',
};

const eventLabel = {
  OPENED: 'ALARME ABERTO',
  ESCALATED: 'ALARME ESCALADO',
  RESOLVED: 'ALARME RESOLVIDO',
};

const typeLabel = {
  INTERFACE_DOWN: 'Interface DOWN',
  INTERFACE_ERRORS: 'Erros de interface',
  INTERFACE_CRC: 'CRC / FCS',
  INTERFACE_DISCARDS: 'Discards',
  OPTICAL_RX_DEGRADATION: 'Degradação óptica',
};

const event = p.event ?? 'OPENED';
const severity = p.severity ?? 'INFO';
const isTest = p.test === true;

const lines = [];

if (isTest) {
  lines.push('🧪 <b>TESTE — GMJ NETVISION</b>');
} else {
  lines.push(`${eventIcon[event] ?? '🔔'} <b>${eventLabel[event] ?? esc(event)}</b>`);
}

lines.push('');

lines.push(
  `${severityIcon[severity] ?? '⚪'} <b>Severidade:</b> ${esc(severity)}`
);

lines.push(
  `📋 <b>Tipo:</b> ${esc(typeLabel[p.type] ?? p.type ?? 'N/D')}`
);

if (p.device?.name || p.deviceName) {
  lines.push(
    `🖥️ <b>Equipamento:</b> ${esc(p.device?.name ?? p.deviceName)}`
  );
}

const ifName = p.interface?.name ?? p.interfaceName;
const ifAlias = p.interface?.alias ?? p.interfaceLabel;

if (ifName) {
  lines.push(`🔌 <b>Interface:</b> ${esc(ifName)}`);
}

if (ifAlias) {
  lines.push(`🏷️ <b>Descrição:</b> ${esc(ifAlias)}`);
}

if (p.linkLabel) {
  lines.push(`🔗 <b>Enlace:</b> ${esc(p.linkLabel)}`);
}

if (p.direction) {
  lines.push(`↔️ <b>Direção:</b> ${esc(p.direction)}`);
}

if (p.lane !== null && p.lane !== undefined) {
  lines.push(`🧵 <b>Lane:</b> ${esc(p.lane)}`);
}

if (p.currentValue !== null && p.currentValue !== undefined) {
  const unit = p.unit ? ` ${p.unit}` : '';
  lines.push(
    `📈 <b>Valor atual:</b> ${esc(p.currentValue)}${esc(unit)}`
  );
}

if (p.thresholdValue !== null && p.thresholdValue !== undefined) {
  const unit = p.unit ? ` ${p.unit}` : '';
  lines.push(
    `🎯 <b>Threshold:</b> ${esc(p.thresholdValue)}${esc(unit)}`
  );
}

const optical = p.optical ?? null;

if (
  optical ||
  p.rxPowerDbm !== null && p.rxPowerDbm !== undefined
) {
  lines.push('');
  lines.push('🔦 <b>Óptico</b>');

  const rx = optical?.rxPowerDbm ?? p.rxPowerDbm;
  const low = optical?.lowThresholdDbm ?? p.rxLowAlarmDbm;
  const high = optical?.highThresholdDbm ?? p.rxHighAlarmDbm;
  const proximity = optical?.proximityPercent ?? p.proximityPercent;
  const drop = optical?.dropDb ?? p.trendDropDb;
  const windowMin = optical?.dropWindowMinutes ?? p.trendWindowMinutes;
  const reasons = optical?.triggerReasons ?? p.triggerReasons;

  if (rx !== null && rx !== undefined)
    lines.push(`• RX: <b>${esc(rx)} dBm</b>`);

  if (low !== null && low !== undefined)
    lines.push(`• LOW: ${esc(low)} dBm`);

  if (high !== null && high !== undefined)
    lines.push(`• HIGH: ${esc(high)} dBm`);

  if (proximity !== null && proximity !== undefined)
    lines.push(`• Proximidade: ${esc(proximity)}%`);

  if (drop !== null && drop !== undefined) {
    lines.push(
      `• Queda: ${esc(drop)} dB${windowMin ? ` / ${esc(windowMin)} min` : ''}`
    );
  }

  if (Array.isArray(reasons) && reasons.length) {
    lines.push(`• Motivo: ${esc(reasons.join(', '))}`);
  }

  if (p.thresholdSource) {
    lines.push(`• Fonte threshold: ${esc(p.thresholdSource)}`);
  }
}

if (p.message) {
  lines.push('');
  lines.push(`💬 ${esc(p.message)}`);
}

lines.push('');

const when =
  p.occurredAt ??
  p.startedAt ??
  p.resolvedAt;

if (when) {
  lines.push(`🕒 ${fmtDate(when)}`);
}

if (p.alarmId) {
  lines.push(`<code>${esc(p.alarmId)}</code>`);
}

return [{
  json: {
    ...$json,
    telegramText: lines.join('\n'),
    alarmEvent: event,
    alarmSeverity: severity,
    isTest,
  }
}];

