  if (affected.length > 0) {
    linhas.push('');
    linhas.push('<b>Escopo atual:</b>');
    for (const item of affected) {
      linhas.push('\u2022 ' + esc(item.interfaceName || item.profileId) + ' \u2014 ' + esc(item.customer || 'sem cliente') + ' \u2014 peer ' + esc(item.peerAddress || '-') + ' (' + esc(item.runtimeState) + ')');
    }
  }
  if (novoToken) {
    linhas.push('');
    linhas.push('Nova confirma\u00E7\u00E3o v\u00E1lida at\u00E9: ' + esc(confirm.expiresAt));
  }
}

return [{ json: {
  ok: ok,
  status: r.status || null,
  verified: ok,
  chatId: cb.chatId,
  messageId: cb.messageId,
  newToken: novoToken,
  text: linhas.join('\n'),
} }];

