}

const transporte =
  (input.error !== undefined && input.error !== null) ||
  (r.error !== undefined && r.error !== null);

const revogado = !transporte && r.ok === true;
const status = transporte ? 'API_INDISPONIVEL' : (r.status || 'SEM_RESPOSTA');

